<?php require_once __DIR__.'/../inc/functions.php';header('Content-Type: application/json; charset=utf-8');require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'errors'=>['طريقة الطلب غير مسموحة']],JSON_UNESCAPED_UNICODE);exit;}if(!hash_equals(csrf_token(),$_POST['csrf_token']??'')){http_response_code(419);echo json_encode(['ok'=>false,'errors'=>['انتهت صلاحية الطلب']],JSON_UNESCAPED_UNICODE);exit;}$errors=[];$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if($name===''||mb_strlen($name)>100)$errors[]='الاسم مطلوب وبحد أقصى 100 محرف.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>100)$errors[]='البريد الإلكتروني غير صحيح.';if($phone===''||mb_strlen($phone)>15)$errors[]='الهاتف مطلوب وبحد أقصى 15 محرفاً.';if($address==='')$errors[]='العنوان مطلوب.';echo json_encode(['ok'=>!$errors,'errors'=>$errors],JSON_UNESCAPED_UNICODE);